import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  OnGatewayConnection,
  OnGatewayDisconnect,
  MessageBody,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger } from '@nestjs/common';

interface CommandPayload {
  command: string;
}

@WebSocketGateway({
  namespace: 'terminal',
  cors: {
    origin: [
      'https://portfolio.jorgedoicela.com',
      'http://localhost:3001',
    ],
    credentials: true,
  },
})
export class TerminalGateway implements OnGatewayConnection, OnGatewayDisconnect {
  @WebSocketServer()
  private readonly server: Server;
  private readonly logger = new Logger(TerminalGateway.name);

  handleConnection(client: Socket) {
    this.logger.log(`Cliente conectado a terminal: ${client.id}`);
    client.emit('terminal-output', {
      text: 'SSH Terminal v2.4.0 — Jorge Doicela OS\nEscribe "help" para listar los comandos disponibles.\n',
      type: 'system',
    });
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Cliente desconectado: ${client.id}`);
  }

  @SubscribeMessage('execute-command')
  handleExecuteCommand(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: CommandPayload,
  ) {
    const trimmed = (payload?.command || '').trim();
    this.logger.debug(`Comando recibido de [${client.id}]: ${trimmed}`);

    if (!trimmed) {
      client.emit('terminal-output', { text: '', prompt: true });
      return;
    }

    // Procesador de comandos virtual seguro (cero llamadas de sistema no autorizadas)
    switch (trimmed.toLowerCase()) {
      case 'help':
        client.emit('terminal-output', {
          text: 'Comandos disponibles:\n  about       Información sobre el autor\n  skills      Matriz de tecnologías y stack\n  projects    Proyectos en producción\n  clear       Limpiar la pantalla de la consola\n',
          type: 'stdout',
          prompt: true,
        });
        break;
      case 'clear':
        client.emit('terminal-clear');
        break;
      default:
        client.emit('terminal-output', {
          text: `bash: comando no encontrado: ${trimmed}\nEscribe "help" para ver opciones.\n`,
          type: 'stderr',
          prompt: true,
        });
        break;
    }
  }
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { io, Socket } from 'socket.io-client';

export interface TerminalLine {
  id: string;
  text: string;
  type: 'stdout' | 'stderr' | 'system' | 'command';
}

export type ConnectionStatus = 'connecting' | 'connected' | 'disconnected' | 'error';

export function useTerminalSocket(socketUrl: string = '/terminal') {
  const [status, setStatus] = useState<ConnectionStatus>('connecting');
  const [lines, setLines] = useState<TerminalLine[]>([]);
  const socketRef = useRef<Socket | null>(null);

  // Buffer de historial de comandos para navegación con flechas
  const historyRef = useRef<string[]>([]);
  const historyIndexRef = useRef<number>(-1);

  useEffect(() => {
    const socket = io(socketUrl, {
      transports: ['websocket'],
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });
    socketRef.current = socket;

    socket.on('connect', () => {
      setStatus('connected');
    });

    socket.on('disconnect', () => {
      setStatus('disconnected');
    });

    socket.on('connect_error', () => {
      setStatus('error');
    });

    socket.on('terminal-output', (payload: { text: string; type?: TerminalLine['type'] }) => {
      setLines((prev) => [
        ...prev,
        {
          id: `${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
          text: payload.text,
          type: payload.type || 'stdout',
        },
      ]);
    });

    socket.on('terminal-clear', () => {
      setLines([]);
    });

    return () => {
      socket.disconnect();
      socketRef.current = null;
    };
  }, [socketUrl]);

  const sendCommand = useCallback((cmd: string) => {
    if (!socketRef.current || !cmd.trim()) return;

    // Registrar comando en la visualización local
    setLines((prev) => [
      ...prev,
      { id: `${Date.now()}-cmd`, text: `$ ${cmd}`, type: 'command' },
    ]);

    // Actualizar historial de comandos
    historyRef.current.push(cmd);
    historyIndexRef.current = historyRef.current.length;

    socketRef.current.emit('execute-command', { command: cmd });
  }, []);

  const navigateHistory = useCallback((direction: 'up' | 'down'): string => {
    const history = historyRef.current;
    if (history.length === 0) return '';

    if (direction === 'up') {
      historyIndexRef.current = Math.max(0, historyIndexRef.current - 1);
    } else {
      historyIndexRef.current = Math.min(history.length, historyIndexRef.current + 1);
    }

    return history[historyIndexRef.current] || '';
  }, []);

  return { status, lines, sendCommand, navigateHistory, clearLines: () => setLines([]) };
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useTerminalSocket, TerminalLine } from './useTerminalSocket';

export function TerminalConsole() {
  const { status, lines, sendCommand, navigateHistory } = useTerminalSocket('/terminal');
  const [inputVal, setInputVal] = useState('');
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Auto-scroll reactivo al fondo ante nuevas líneas de salida
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [lines]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      sendCommand(inputVal);
      setInputVal('');
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setInputVal(navigateHistory('up'));
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      setInputVal(navigateHistory('down'));
    }
  };

  const getLineClass = (type: TerminalLine['type']) => {
    switch (type) {
      case 'command':
        return 'text-cyan-400 font-bold';
      case 'stderr':
        return 'text-rose-400';
      case 'system':
        return 'text-amber-400/90 font-semibold';
      case 'stdout':
      default:
        return 'text-emerald-400';
    }
  };

  return (
    <div
      onClick={() => inputRef.current?.focus()}
      className="w-full max-w-4xl mx-auto rounded-2xl bg-zinc-950 border border-white/10 shadow-2xl overflow-hidden font-mono text-xs sm:text-sm cursor-text"
    >
      {/* Barra de Título Neumórfica de la Terminal */}
      <div className="flex items-center justify-between px-4 py-2.5 bg-zinc-900/90 border-b border-white/5 select-none">
        <div className="flex items-center gap-2">
          <span className="w-3 h-3 rounded-full bg-rose-500/80 inline-block" />
          <span className="w-3 h-3 rounded-full bg-amber-500/80 inline-block" />
          <span className="w-3 h-3 rounded-full bg-emerald-500/80 inline-block" />
          <span className="ml-2 text-zinc-400 text-xs font-semibold">guest@jorgedoicela: ~ (ssh)</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-400 animate-pulse' : 'bg-rose-400'}`} />
          <span className="text-[10px] text-zinc-400 uppercase">{status}</span>
        </div>
      </div>

      {/* Contenedor de Salida con Scroll */}
      <div className="p-4 sm:p-6 min-h-[340px] max-h-[500px] overflow-y-auto space-y-1 scrollbar-thin scrollbar-thumb-zinc-800">
        {lines.map((l) => (
          <div key={l.id} className={`whitespace-pre-wrap leading-relaxed ${getLineClass(l.type)}`}>
            {l.text}
          </div>
        ))}

        {/* Línea de Prompt Activa */}
        <div className="flex items-center gap-2 pt-1 text-slate-200">
          <span className="text-cyan-400 font-bold select-none">guest@vps:~$</span>
          <input
            ref={inputRef}
            type="text"
            value={inputVal}
            onChange={(e) => setInputVal(e.target.value)}
            onKeyDown={handleKeyDown}
            className="flex-1 bg-transparent border-none outline-none text-emerald-400 font-mono caret-cyan-400 p-0 m-0"
            autoFocus
            spellCheck={false}
            autoComplete="off"
          />
        </div>
        <div ref={bottomRef} />
      </div>
    </div>
  );
}

